#!/usr/bin/env python3\n\"\"\"\nOptimized Production-Ready ML Model Test Suite for FX AI-Quant Trading System.\n\nThis test suite addresses the performance issues found in the initial production test:\n- Optimizes model architectures for faster inference\n- Reduces model complexity while maintaining accuracy\n- Implements production-ready optimizations\n\"\"\"\n\nimport os\n# Disable oneDNN optimizations to avoid pooling issues\nos.environ['TF_ENABLE_ONEDNN_OPTS'] = '0'\n\nimport asyncio\nimport sys\nimport time\nimport json\nfrom pathlib import Path\nfrom typing import Dict, List, Any, Optional, Tuple\nfrom datetime import datetime\nimport numpy as np\nimport pandas as pd\nimport structlog\n\n# Add project root to path\nsys.path.append(str(Path(__file__).parent))\n\n# Import all necessary modules\nfrom models.predictor_interface import PredictionType, ModelType, ModelConfig, TrainingMetrics\nfrom models import (\n    get_available_models, create_model,\n    LSTM_AVAILABLE, CNN_AVAILABLE, ENSEMBLE_AVAILABLE\n)\nfrom core.interfaces.ml_interfaces import Features, Prediction\n\n# Configure logging\nstructlog.configure(\n    processors=[\n        structlog.stdlib.filter_by_level,\n        structlog.stdlib.add_logger_name,\n        structlog.stdlib.add_log_level,\n        structlog.stdlib.PositionalArgumentsFormatter(),\n        structlog.processors.TimeStamper(fmt=\"iso\"),\n        structlog.processors.StackInfoRenderer(),\n        structlog.processors.format_exc_info,\n        structlog.processors.UnicodeDecoder(),\n        structlog.processors.JSONRenderer()\n    ],\n    context_class=dict,\n    logger_factory=structlog.stdlib.LoggerFactory(),\n    wrapper_class=structlog.stdlib.BoundLogger,\n    cache_logger_on_first_use=True,\n)\n\nlogger = structlog.get_logger()\n\nclass OptimizedMLProductionTester:\n    \"\"\"Optimized production test suite for ML models.\"\"\"\n    \n    def __init__(self):\n        self.logger = logger\n        self.test_results = {}\n        self.start_time = datetime.now().isoformat()\n        \n        # Performance benchmarks (optimized)\n        self.benchmarks = {\n            'max_inference_time': 0.05,  # Reduced from 0.1s to 0.05s\n            'max_training_time': 180.0,  # Reduced from 300s to 180s\n            'min_sharpe_ratio': 0.5,     # More realistic threshold\n            'max_drawdown_threshold': -0.2,\n            'min_accuracy': 0.6,\n            'max_memory_mb': 500.0\n        }\n        \n    def create_optimized_configs(self) -> Dict[str, ModelConfig]:\n        \"\"\"Create optimized model configurations for faster inference.\"\"\"\n        configs = {}\n        \n        # Optimized LSTM Configuration - Smaller, faster model\n        if LSTM_AVAILABLE:\n            from models.lstm_model import create_lstm_config\n            configs[\"lstm\"] = create_lstm_config(\n                prediction_type=PredictionType.RETURN_REGRESSION,\n                sequence_length=30,  # Reduced from 60\n                features_dim=13,\n                lstm_units=32,       # Reduced from 64\n                num_layers=1,        # Reduced from 2\n                dropout_rate=0.1,    # Reduced dropout\n                recurrent_dropout=0.1,\n                use_bidirectional=False,  # Disabled for speed\n                learning_rate=0.002,      # Increased for faster convergence\n                batch_size=128,           # Increased batch size\n                epochs=10,                # Reduced epochs\n                validation_split=0.2,\n                early_stopping_patience=5\n            )\n        \n        # Optimized CNN Configuration - Lighter architecture\n        if CNN_AVAILABLE:\n            from models.cnn_model import create_cnn_config\n            configs[\"cnn\"] = create_cnn_config(\n                prediction_type=PredictionType.RETURN_REGRESSION,\n                sequence_length=30,  # Reduced from 60\n                features_dim=13,\n                cnn_filters=32,      # Reduced from 64\n                kernel_sizes=[3, 5], # Reduced kernel variety\n                num_conv_layers=2,   # Reduced from 3\n                learning_rate=0.002,\n                batch_size=128,\n                epochs=10,\n                validation_split=0.2,\n                early_stopping_patience=5,\n                pool_size=2,\n                dropout_rate=0.2,    # Reduced dropout\n                use_batch_norm=True\n            )\n        \n        # XGBoost Configuration - Already optimized\n        configs[\"xgboost\"] = self._create_xgboost_config()\n        \n        return configs\n    \n    def _create_xgboost_config(self) -> ModelConfig:\n        \"\"\"Create optimized XGBoost configuration.\"\"\"\n        from models.ensemble_model import create_xgboost_config\n        return create_xgboost_config(\n            prediction_type=PredictionType.RETURN_REGRESSION,\n            n_estimators=100,    # Reduced from 200\n            max_depth=4,         # Reduced from 6\n            learning_rate=0.15,  # Increased for faster convergence\n            sequence_length=30,  # Reduced sequence length\n            features_dim=13,\n            subsample=0.8,\n            colsample_bytree=0.8,\n            random_state=42,\n            n_jobs=-1\n        )\n    \n    def generate_optimized_data(self, n_samples: int = 3000) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:\n        \"\"\"Generate optimized synthetic FX data for testing.\"\"\"\n        self.logger.info(\"Generating optimized synthetic FX data\", samples=n_samples)\n        \n        # Reduced sample size for faster testing\n        np.random.seed(42)\n        \n        # Generate more realistic FX returns\n        base_return = np.random.normal(0, 0.01, n_samples)\n        trend = np.sin(np.linspace(0, 4*np.pi, n_samples)) * 0.005\n        noise = np.random.normal(0, 0.002, n_samples)\n        \n        returns = base_return + trend + noise\n        \n        # Generate correlated features\n        features = np.zeros((n_samples, 13))\n        features[:, 0] = returns  # price_return\n        \n        for i in range(1, 13):\n            # Create features with varying correlation to returns\n            correlation = np.random.uniform(0.1, 0.8)\n            features[:, i] = correlation * returns + (1 - correlation) * np.random.normal(0, 0.01, n_samples)\n        \n        # Create sequences with reduced length\n        sequence_length = 30\n        X_sequences = []\n        y_sequences = []\n        \n        for i in range(sequence_length, n_samples):\n            X_sequences.append(features[i-sequence_length:i])\n            y_sequences.append(returns[i])\n        \n        X = np.array(X_sequences)\n        y = np.array(y_sequences)\n        \n        # Split data\n        train_size = int(0.7 * len(X))\n        val_size = int(0.15 * len(X))\n        \n        X_train = X[:train_size]\n        y_train = y[:train_size]\n        X_val = X[train_size:train_size + val_size]\n        y_val = y[train_size:train_size + val_size]\n        X_test = X[train_size + val_size:]\n        y_test = y[train_size + val_size:]\n        \n        self.logger.info(\n            \"Data generation complete\",\n            train_samples=len(X_train),\n            val_samples=len(X_val),\n            test_samples=len(X_test),\n            sequence_length=sequence_length,\n            features=13\n        )\n        \n        return X_train, y_train, X_val, y_val, X_test, y_test\n    \n    async def test_model_performance(self, model_name: str, config: ModelConfig, \n                                   X_train: np.ndarray, y_train: np.ndarray,\n                                   X_val: np.ndarray, y_val: np.ndarray,\n                                   X_test: np.ndarray, y_test: np.ndarray) -> Dict[str, Any]:\n        \"\"\"Test individual model performance with optimizations.\"\"\"\n        \n        self.logger.info(f\"Testing optimized {model_name} model\")\n        \n        try:\n            # Create model\n            start_time = time.time()\n            model = create_model(config)\n            creation_time = time.time() - start_time\n            \n            # Train model\n            self.logger.info(f\"Training {model_name} model\")\n            start_time = time.time()\n            \n            training_metrics = await model.train(X_train, y_train, X_val, y_val)\n            training_time = time.time() - start_time\n            \n            # Test inference speed with multiple runs\n            inference_times = []\n            for _ in range(20):  # Test 20 predictions for average\n                start_time = time.time()\n                _ = await model.predict(X_test[:1])\n                inference_times.append(time.time() - start_time)\n            \n            avg_inference_time = np.mean(inference_times)\n            max_inference_time = np.max(inference_times)\n            \n            # Evaluate on test set\n            predictions = await model.predict(X_test)\n            \n            # Calculate metrics\n            mse = np.mean((predictions - y_test) ** 2)\n            mae = np.mean(np.abs(predictions - y_test))\n            rmse = np.sqrt(mse)\n            \n            # Calculate Sharpe ratio (annualized)\n            returns = predictions\n            if np.std(returns) > 0:\n                sharpe_ratio = np.mean(returns) / np.std(returns) * np.sqrt(252)\n            else:\n                sharpe_ratio = 0\n            \n            # Calculate max drawdown\n            cumulative_returns = np.cumsum(returns)\n            running_max = np.maximum.accumulate(cumulative_returns)\n            drawdown = cumulative_returns - running_max\n            max_drawdown = np.min(drawdown) if len(drawdown) > 0 else 0\n            \n            # Performance checks\n            errors = []\n            warnings = []\n            \n            if avg_inference_time > self.benchmarks['max_inference_time']:\n                errors.append(f\"Average inference time {avg_inference_time:.4f}s exceeds benchmark {self.benchmarks['max_inference_time']}s\")\n            \n            if training_time > self.benchmarks['max_training_time']:\n                warnings.append(f\"Training time {training_time:.2f}s exceeds benchmark {self.benchmarks['max_training_time']}s\")\n            \n            if sharpe_ratio < self.benchmarks['min_sharpe_ratio']:\n                warnings.append(f\"Sharpe ratio {sharpe_ratio:.3f} below threshold {self.benchmarks['min_sharpe_ratio']}\")\n            \n            # Test production scenarios\n            production_tests = await self._test_production_scenarios(model, X_test)\n            \n            result = {\n                'model_type': model_name,\n                'config': self._serialize_config(config),\n                'training_metrics': {\n                    'train_loss': float(training_metrics.train_loss) if training_metrics.train_loss else None,\n                    'val_loss': float(training_metrics.val_loss) if training_metrics.val_loss else None,\n                    'training_time': training_time,\n                },\n                'test_metrics': {\n                    'mse': float(mse),\n                    'mae': float(mae),\n                    'rmse': float(rmse),\n                    'sharpe_ratio': float(sharpe_ratio),\n                    'max_drawdown': float(max_drawdown)\n                },\n                'performance_metrics': {\n                    'creation_time': creation_time,\n                    'training_time': training_time,\n                    'avg_inference_time': avg_inference_time,\n                    'max_inference_time': max_inference_time,\n                },\n                'production_tests': production_tests,\n                'errors': errors,\n                'warnings': warnings,\n                'passed': len(errors) == 0\n            }\n            \n            self.logger.info(\n                f\"{model_name} test completed\",\n                passed=result['passed'],\n                errors=len(errors),\n                warnings=len(warnings),\n                avg_inference_time=avg_inference_time,\n                sharpe_ratio=sharpe_ratio\n            )\n            \n            return result\n            \n        except Exception as e:\n            self.logger.error(f\"Error testing {model_name} model\", error=str(e))\n            return {\n                'model_type': model_name,\n                'error': str(e),\n                'passed': False\n            }\n    \n    async def _test_production_scenarios(self, model, X_test: np.ndarray) -> Dict[str, Any]:\n        \"\"\"Test production scenarios.\"\"\"\n        \n        # Single prediction test\n        single_pred = await model.predict(X_test[:1])\n        \n        # Batch prediction test\n        batch_pred = await model.predict(X_test[:5])\n        \n        # Edge case tests\n        edge_cases = {}\n        \n        try:\n            # Zero input\n            zero_input = np.zeros_like(X_test[:1])\n            _ = await model.predict(zero_input)\n            edge_cases['zero_input'] = 'success'\n        except Exception as e:\n            edge_cases['zero_input'] = f'error: {str(e)}'\n        \n        try:\n            # Extreme values\n            extreme_input = X_test[:1] * 100\n            _ = await model.predict(extreme_input)\n            edge_cases['extreme_values'] = 'success'\n        except Exception as e:\n            edge_cases['extreme_values'] = f'error: {str(e)}'\n        \n        return {\n            'single_prediction': {\n                'prediction': float(single_pred[0]) if len(single_pred) > 0 else None,\n                'symbol': 'EURUSD',\n                'model_name': model.config.model_type.value\n            },\n            'batch_prediction': {\n                'num_predictions': len(batch_pred),\n                'predictions': [float(p) for p in batch_pred[:3]]  # First 3 predictions\n            },\n            'edge_cases': edge_cases\n        }\n    \n    def _serialize_config(self, config: ModelConfig) -> Dict[str, Any]:\n        \"\"\"Serialize model config for JSON output.\"\"\"\n        result = {}\n        for key, value in config.__dict__.items():\n            if hasattr(value, 'value'):  # Enum\n                result[key] = str(value)\n            elif isinstance(value, (list, tuple)):\n                result[key] = list(value)\n            else:\n                result[key] = value\n        return result\n    \n    async def run_optimized_tests(self) -> Dict[str, Any]:\n        \"\"\"Run the complete optimized test suite.\"\"\"\n        \n        self.logger.info(\"Starting optimized ML production test suite\")\n        \n        # Generate test data\n        X_train, y_train, X_val, y_val, X_test, y_test = self.generate_optimized_data()\n        \n        # Create optimized configurations\n        configs = self.create_optimized_configs()\n        \n        # Test each model\n        model_results = {}\n        for model_name, config in configs.items():\n            if model_name in get_available_models():\n                result = await self.test_model_performance(\n                    model_name, config, X_train, y_train, X_val, y_val, X_test, y_test\n                )\n                model_results[model_name] = result\n        \n        # Calculate summary\n        passed_tests = sum(1 for result in model_results.values() if result.get('passed', False))\n        total_tests = len(model_results)\n        success_rate = (passed_tests / total_tests * 100) if total_tests > 0 else 0\n        \n        # Generate recommendations\n        recommendations = self._generate_recommendations(model_results)\n        \n        final_results = {\n            'start_time': self.start_time,\n            'test_environment': {\n                'available_models': get_available_models(),\n                'optimizations_applied': [\n                    'Reduced sequence length (60 -> 30)',\n                    'Smaller model architectures',\n                    'Faster training (reduced epochs)',\n                    'Optimized batch sizes',\n                    'Stricter performance benchmarks'\n                ]\n            },\n            'model_tests': model_results,\n            'summary': {\n                'total_tests': total_tests,\n                'passed_tests': passed_tests,\n                'success_rate': success_rate\n            },\n            'recommendations': recommendations,\n            'passed': passed_tests == total_tests\n        }\n        \n        # Save results\n        self._save_results(final_results)\n        \n        return final_results\n    \n    def _generate_recommendations(self, model_results: Dict[str, Any]) -> List[str]:\n        \"\"\"Generate recommendations based on test results.\"\"\"\n        recommendations = []\n        \n        passed_models = [name for name, result in model_results.items() if result.get('passed', False)]\n        failed_models = [name for name, result in model_results.items() if not result.get('passed', False)]\n        \n        if len(passed_models) >= 2:\n            recommendations.append(\"✅ Multiple models passed - ensemble approach recommended for production\")\n        elif len(passed_models) == 1:\n            recommendations.append(f\"✅ {passed_models[0]} model ready for production deployment\")\n        \n        for model_name in failed_models:\n            result = model_results[model_name]\n            if result.get('errors'):\n                recommendations.append(f\"❌ {model_name}: {result['errors'][0]}\")\n        \n        if 'xgboost' in passed_models:\n            recommendations.append(\"✅ XGBoost shows excellent performance for production use\")\n        \n        return recommendations\n    \n    def _save_results(self, results: Dict[str, Any]):\n        \"\"\"Save test results to files.\"\"\"\n        \n        # Save JSON report\n        json_path = Path('ml_optimized_test_report.json')\n        with open(json_path, 'w', encoding='utf-8') as f:\n            json.dump(results, f, indent=2, default=str)\n        \n        # Save human-readable summary\n        txt_path = Path('ml_optimized_test_report.txt')\n        with open(txt_path, 'w', encoding='utf-8') as f:\n            f.write(\"FX AI-Quant Trading System - Optimized ML Production Test Report\\n\")\n            f.write(\"=\" * 70 + \"\\n\\n\")\n            \n            f.write(f\"Test Date: {results['start_time']}\\n\")\n            f.write(f\"Overall Result: {'PASSED' if results['passed'] else 'FAILED'}\\n\\n\")\n            \n            summary = results['summary']\n            f.write(f\"Tests Passed: {summary['passed_tests']}/{summary['total_tests']}\\n\")\n            f.write(f\"Success Rate: {summary['success_rate']:.1f}%\\n\\n\")\n            \n            f.write(\"Optimizations Applied:\\n\")\n            for opt in results['test_environment']['optimizations_applied']:\n                f.write(f\"• {opt}\\n\")\n            f.write(\"\\n\")\n            \n            f.write(\"Model Test Results:\\n\")\n            f.write(\"-\" * 20 + \"\\n\")\n            for model_name, result in results['model_tests'].items():\n                status = \"PASSED\" if result.get('passed', False) else \"FAILED\"\n                f.write(f\"{model_name.upper()}: {status}\\n\")\n                \n                if result.get('performance_metrics'):\n                    perf = result['performance_metrics']\n                    f.write(f\"  Inference Time: {perf.get('avg_inference_time', 0):.4f}s\\n\")\n                \n                if result.get('test_metrics'):\n                    metrics = result['test_metrics']\n                    f.write(f\"  Sharpe Ratio: {metrics.get('sharpe_ratio', 0):.3f}\\n\")\n                \n                if result.get('errors'):\n                    f.write(f\"  Errors: {len(result['errors'])}\\n\")\n                if result.get('warnings'):\n                    f.write(f\"  Warnings: {len(result['warnings'])}\\n\")\n                f.write(\"\\n\")\n            \n            f.write(\"Recommendations:\\n\")\n            f.write(\"-\" * 15 + \"\\n\")\n            for rec in results['recommendations']:\n                f.write(f\"• {rec}\\n\")\n        \n        self.logger.info(\n            \"Test results saved\",\n            json_report=str(json_path),\n            text_report=str(txt_path)\n        )\n\nasync def main():\n    \"\"\"Run the optimized production test suite.\"\"\"\n    \n    print(\"🚀 Starting Optimized ML Production Test Suite...\")\n    print(\"=\" * 60)\n    \n    tester = OptimizedMLProductionTester()\n    \n    try:\n        results = await tester.run_optimized_tests()\n        \n        print(\"\\n\" + \"=\" * 60)\n        print(\"📊 OPTIMIZED TEST RESULTS SUMMARY\")\n        print(\"=\" * 60)\n        \n        summary = results['summary']\n        print(f\"Tests Passed: {summary['passed_tests']}/{summary['total_tests']}\")\n        print(f\"Success Rate: {summary['success_rate']:.1f}%\")\n        print(f\"Overall Result: {'✅ PASSED' if results['passed'] else '❌ FAILED'}\")\n        \n        print(\"\\nModel Results:\")\n        for model_name, result in results['model_tests'].items():\n            status = \"✅ PASSED\" if result.get('passed', False) else \"❌ FAILED\"\n            print(f\"  {model_name.upper()}: {status}\")\n            \n            if result.get('performance_metrics'):\n                perf = result['performance_metrics']\n                print(f\"    Inference: {perf.get('avg_inference_time', 0):.4f}s\")\n        \n        print(\"\\nRecommendations:\")\n        for rec in results['recommendations']:\n            print(f\"  • {rec}\")\n        \n        print(\"\\n📁 Detailed reports saved:\")\n        print(\"  • ml_optimized_test_report.json\")\n        print(\"  • ml_optimized_test_report.txt\")\n        \n        if results['passed']:\n            print(\"\\n🎉 All optimized tests passed! Models are production-ready.\")\n        else:\n            print(\"\\n⚠️  Some tests failed. Review recommendations for improvements.\")\n            \n    except Exception as e:\n        print(f\"\\n❌ Test suite failed with error: {e}\")\n        import traceback\n        traceback.print_exc()\n        return False\n    \n    return results['passed']\n\nif __name__ == \"__main__\":\n    success = asyncio.run(main())
